import{_ as t,o as a,c as o,a7 as r}from"./chunks/framework.Du_9D64Q.js";const f=JSON.parse('{"title":"Why PHP?","description":"Why PHP was chosen for making Axolotl-PM (PocketMine).","frontmatter":{"title":"Why PHP?","outline":"deep","description":"Why PHP was chosen for making Axolotl-PM (PocketMine).","head":[["link",{"rel":"canonical","href":"https://axolotl-pm.org/docs/faq/about/why-php"}]]},"headers":[],"relativePath":"docs/faq/about/why-php.md","filePath":"docs/faq/about/why-php.md","lastUpdated":1790689997000}'),s={name:"docs/faq/about/why-php.md"};function n(i,e,l,h,c,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="why-php" tabindex="-1">Why PHP? <a class="header-anchor" href="#why-php" aria-label="Permalink to &quot;Why PHP?&quot;">​</a></h1><p>Back in its early days, PocketMine-MP (at the time known as <a href="https://github.com/axolotl-pm/PocketMine-MP/commit/ba3524dbc7ea98d305c74f00ea6c9a260402c928" target="_blank" rel="noreferrer">Pocket Minecraft PHP</a>) was intended as a <strong>quick prototype</strong> for reverse engineering the Minecraft PE protocol by its creator, <a href="https://github.com/shoghicp" target="_blank" rel="noreferrer">Shoghi Cervantes</a>. It was <strong>never intended</strong> for use on production servers. (<a href="https://twitter.com/shoghicp/status/931944880733081601" target="_blank" rel="noreferrer">Tweet from @shoghicp</a>)</p><p>Since PocketMine-MP was the only server software available for Minecraft PE at the time, it quickly grew in popularity and started to be used by thousands of servers. <a href="https://lbsg.net" target="_blank" rel="noreferrer">Lifeboat Survival Games</a> was one of the first big servers in Minecraft PE, and it was built using PocketMine-MP.</p><p>PMMP was popular because it was the oldest and most well-known Bedrock server software out there, as well as being really easy to develop plugins for.</p><p>Axolotl-PM is an actively maintained fork of PMMP, so it is written in PHP as well. PMMP plugins are compatible with Axolotl-PM unless they use the network API.</p>',5)])])}const d=t(s,[["render",n]]);export{f as __pageData,d as default};
